declare(strict_types=1);namespace Pam\Native\LiveActivities;use Closure;use InvalidArgumentException;use Pam\Native\Modules\NativeModuleResult;use Pam\Native\Modules\NativeModules;final class LiveActivities{public function start(string$key,LiveActivityContent$content,Closure$complete,bool$pushEnabled=false):int{$this->key($key);return$this->call('start',['key'=>$key,'pushEnabled'=>$pushEnabled,...$content->payload()],$complete);}public function update(string$identifier,LiveActivityContent$content,Closure$complete):int{return$this->call('update',['identifier'=>$identifier,...$content->payload()],$complete);}public function end(string$identifier,LiveActivityContent$content,Closure$complete,bool$immediate=false):int{return$this->call('end',['identifier'=>$identifier,'immediate'=>$immediate,...$content->payload()],$complete);}public function active(Closure$complete):int{return NativeModules::call('live-activities','active',[],static function(NativeModuleResult$r)use($complete){$complete($r->succeeded()?json_decode((string)($r->values()['json']??'[]'),true):[]);});}private function call(string$m,array$p,Closure$c):int{return NativeModules::call('live-activities',$m,$p,static function(NativeModuleResult$r)use($c){$v=$r->values();$c($r->succeeded()?(string)($v['identifier']??''):null,$r->succeeded()?null:$r->message());});}private function key(string$v):void{if(preg_match('/^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/D',$v)!==1)throw new InvalidArgumentException('Invalid live activity key.');}}
